    symbol_count: usize,
    has_error: bool,

    pub fn init() CompilerEngine {
        return CompilerEngine{
            .symbols = undefined,
            .symbol_count = 0,
            .has_error = false,
        };
    }

    pub fn compile_source(self: *CompilerEngine, filename: []const u8, source: []const u8) bool {
        print("\n==========================================================\n", .{});
        print(" SOVRA NATIVE COMPILER (sovrac v1.0) - COMPILING '{s}'\n", .{filename});
        print("==========================================================\n", .{});

        var lex = Lexer.init(source);
        var tok = lex.next_token();

        while (tok.kind != .Eof) {
            if (tok.kind == .KwVal) {
                tok = lex.next_token(); // Variable Name
                const var_name = tok.text;
                const line = tok.line;

                tok = lex.next_token(); // Colon :
                tok = lex.next_token(); // Type Name

                var type_kind: DataType = .Unknown;
                if (tok.kind == .KwCandidate) type_kind = .Candidate;
                if (tok.kind == .KwDecision) type_kind = .Decision;
                if (tok.kind == .KwShmRingBuffer) type_kind = .ShmRingBuffer;
                if (tok.kind == .KwHyperVector) type_kind = .HyperVector;

                if (type_kind == .Candidate or type_kind == .Decision) {
                    tok = lex.next_token(); // <
                    tok = lex.next_token(); // Type
                    tok = lex.next_token(); // >
                }

                tok = lex.next_token(); // Equals =
                tok = lex.next_token(); // RHS Expression

                var is_gated = false;
                if (tok.kind == .KwGate) {
                    is_gated = true;
                } else if (tok.kind == .Identifier) {
                    const rhs_var = tok.text;
                    for (0..self.symbol_count) |s| {
                        if (std.mem.eql(u8, self.symbols[s].name, rhs_var)) {
                            if (self.symbols[s].type_kind == .Candidate and type_kind == .Decision) {
                                print("\n❌ [SOVRA COMPILER TYPE ERROR] Line {}: Invalid type coercion!\n", .{line});
