                                self.has_error = true;
                                return false;
                            }
                        }
                    }
                }

                self.symbols[self.symbol_count] = VarSymbol{
                    .name = var_name,
                    .type_kind = type_kind,
                    .is_gated = is_gated,
                    .line = line,
                };
                self.symbol_count += 1;
            }
            tok = lex.next_token();
        }

        if (self.has_error) return false;

        print("[+] AST Lexing & Parsing: COMPLETED (Source AST Verified)\n", .{});
        print("[+] Type Checker        : PASSED (Capability Boundaries Enforced)\n", .{});
