            }
            if (c == '}') {
                self.cursor += 1;
                return Token{ .kind = .RBrace, .text = "}", .line = self.line };
            }
            if (c == '<') {
                self.cursor += 1;
                return Token{ .kind = .LAngle, .text = "<", .line = self.line };
            }
            if (c == '>') {
                self.cursor += 1;
                return Token{ .kind = .RAngle, .text = ">", .line = self.line };
            }
            if (c == '@') {
                const start = self.cursor;
                self.cursor += 1;
                while (self.cursor < self.source.len and std.ascii.isAlphanumeric(self.source[self.cursor])) {
                    self.cursor += 1;
