// ops/runtime/dynamic_payload_crdt_proof.zig
// Dynamic Payload-Dependent Blackbox Readback Benchmark for Sovra CRDT Graph
// Eliminates algebraic loop reduction by deriving checksums from dynamic, non-predictable node memory contents.

const std = @import("std");
const print = std.debug.print;
const crdt = @import("sovra_crdt_kernel.zig");

const c = @cImport({
    @cInclude("time.h");
});

fn getNanos() u64 {
    var ts: c.struct_timespec = undefined;
    _ = c.clock_gettime(c.CLOCK_MONOTONIC, &ts);
    return @as(u64, @intCast(ts.tv_sec)) * 1_000_000_000 + @as(u64, @intCast(ts.tv_nsec));
}

fn volatileWrite(ptr: *volatile u64, val: u64) void {
    ptr.* = val;
}

// Linear Congruential Generator for non-algebraic, dynamic payload data
fn nextRandom(state: *u64) u64 {
    state.* = state.* *% 6364136223846793005 +% 1442695040888963407;
    return state.*;
}

pub fn main() !void {
    print("==========================================================\n", .{});
    print(" DYNAMIC PAYLOAD-DEPENDENT CRDT BENCHMARK (M4 PHYSICAL SILICON)\n", .{});
    print("==========================================================\n\n", .{});

    var graph = crdt.SovraCrdtGraph.init();
    var rng_seed: u64 = 0xDEADBEEFCAFE1001;

    // 1. Warmup Iteration (10,000 insertions)
    var w: u64 = 0;
    while (w < 10000) : (w += 1) {
        const payload_val = @as(u8, @intCast(nextRandom(&rng_seed) % 255));
        _ = graph.insert_node(w + 1, .Episode, payload_val, 0);
    }
    graph.node_count = 0; // Reset arena
    rng_seed = 0xFEEDBEEF12345678;

    // 2. Volatile Sink setup
    var volatile_checksum: u64 = 0;
    const volatile_ptr: *volatile u64 = &volatile_checksum;

    // 3. High-resolution Monotonic Nanosecond Timer
    const t0 = getNanos();

    var i: u64 = 0;
    while (i < 100000) : (i += 1) {
        // Generate unpredictable dynamic node payload
        const dyn_payload = @as(u8, @intCast(nextRandom(&rng_seed) % 255));
        const ok = graph.insert_node(
            i + 1,
            if (dyn_payload % 2 == 0) .Episode else .Semantic,
            dyn_payload,
            if (i > 0) i else 0,
        );
        if (ok) {
            // Checksum depends strictly on actual written memory contents of node array in RAM
            const written_node = graph.nodes[graph.node_count - 1];
            const payload_hash = @as(u64, written_node.payload_val) *% 1099511628211 +% written_node.version_vector;
            volatileWrite(volatile_ptr, volatile_ptr.* +% payload_hash);
        }
    }

    const t1 = getNanos();
    const total_ns = t1 - t0;
    const total_us = total_ns / 1000;
    const ns_per_op = @as(f64, @floatFromInt(total_ns)) / 100000.0;
    const cycles_per_op = ns_per_op * 3.8; // M4 ~3.8 GHz clock frequency (1 cycle = ~0.263 ns)

    print("[REAL HARDWARE MEASUREMENT RESULTS]\n", .{});
    print("Total Nodes Inserted          : {}\n", .{graph.node_count});
    print("Dynamic Checksum (Consumed)  : {} (Payload-Dependent Memory Hash)\n", .{volatile_checksum});
    print("Total Time Elapsed (ns)       : {} ns\n", .{total_ns});
    print("Total Time Elapsed (us)       : {} us ({d:.3} ms)\n", .{ total_us, @as(f64, @floatFromInt(total_us)) / 1000.0 });
    print("Un-Elided Latency / Op        : {d:.2} ns / insertion\n", .{ns_per_op});
    print("M4 CPU Cycles / Op (@3.8GHz)  : {d:.2} cycles / insertion\n\n", .{cycles_per_op});

    print("==========================================================\n", .{});
}

