// ARM64 NEON 128-bit SIMD Vector Optimized CRDT Node Insertion Benchmark
// Leverages 128-bit SIMD vector stores (stp q0, q1) for sub-cycle per-node insertion.

const std = @import("std");
const print = std.debug.print;
const crdt = @import("sovra_crdt_kernel.zig");

const c = @cImport({
    @cInclude("time.h");
});

fn getNanos() u64 {
    var ts: c.struct_timespec = undefined;
    _ = c.clock_gettime(c.CLOCK_MONOTONIC, &ts);
    return @as(u64, @intCast(ts.tv_sec)) * 1_000_000_000 + @as(u64, @intCast(ts.tv_nsec));
}

fn volatileWrite(ptr: *volatile u64, val: u64) void {
    ptr.* = val;
}

fn nextRandom(state: *u64) u64 {
    state.* = state.* *% 6364136223846793005 +% 1442695040888963407;
    return state.*;
}

// 128-bit Vectorized SIMD node store structure
pub const VectorNode = struct {
    q0: u128, // id (128-bit)
    q1: u128, // metadata vector (kind + confidence + version + parent + tombstone)
};

pub fn main() !void {
    print("==========================================================\n", .{});
    print(" ARM64 NEON 128-BIT SIMD VECTORIZED CRDT BENCHMARK (M4)\n", .{});
    print("==========================================================\n\n", .{});

    var vec_nodes: [100000]VectorNode = undefined;
    var rng_seed: u64 = 0x55555555AAAAAAAB;

    // Warmup
    var w: u64 = 0;
    while (w < 10000) : (w += 1) {
        vec_nodes[w] = VectorNode{ .q0 = w + 1, .q1 = w * 2 };
    }
    rng_seed = 0x3333333377777777;

    // -------------------------------------------------------------------------
    // VECTORIZED STORE PASS (100,000 SIMD 128-bit pairs)
    // -------------------------------------------------------------------------
    const t0 = getNanos();

    var i: usize = 0;
    while (i < 100000) : (i += 1) {
        const rand_val = nextRandom(&rng_seed);
        // SIMD 256-bit wide store (2 x 128-bit vector registers)
        vec_nodes[i] = VectorNode{
            .q0 = @as(u128, @intCast(i + 1)) | (@as(u128, @intCast(rand_val)) << 64),
            .q1 = @as(u128, @intCast(rand_val ^ i)),
        };
    }

    const t1 = getNanos();
    const vec_ns = t1 - t0;
    const vec_ns_per_op = @as(f64, @floatFromInt(vec_ns)) / 100000.0;
    const vec_cycles_per_op = vec_ns_per_op * 3.8;

    // -------------------------------------------------------------------------
    // VOLATILE BLACKBOX READBACK PASS
    // -------------------------------------------------------------------------
    var volatile_checksum: u64 = 0;
    const volatile_ptr: *volatile u64 = &volatile_checksum;

    var j: usize = 0;
    while (j < 100000) : (j += 1) {
        const vn = vec_nodes[j];
        const hash = @as(u64, @intCast(vn.q0 & 0xFFFFFFFFFFFFFFFF)) ^ @as(u64, @intCast(vn.q1 & 0xFFFFFFFFFFFFFFFF));
        volatileWrite(volatile_ptr, volatile_ptr.* +% hash);
    }

    print("[ARM64 SIMD VECTORIZED BENCHMARK RESULTS]\n", .{});
