// NOP-Padded Equal Instruction Count Benchmark & N=30 Statistical Analysis for M4
// Guarantees identical instruction counts (8 instrs/iter) between Interleaved and Decoupled loops.

const std = @import("std");
const print = std.debug.print;
const crdt = @import("sovra_crdt_kernel.zig");

const c = @cImport({
    @cInclude("time.h");
});

fn getNanos() u64 {
    var ts: c.struct_timespec = undefined;
    _ = c.clock_gettime(c.CLOCK_MONOTONIC, &ts);
    return @as(u64, @intCast(ts.tv_sec)) * 1_000_000_000 + @as(u64, @intCast(ts.tv_nsec));
}

fn volatileWrite(ptr: *volatile u64, val: u64) void {
    ptr.* = val;
}

fn nextRandom(state: *u64) u64 {
    state.* = state.* *% 6364136223846793005 +% 1442695040888963407;
    return state.*;
}

// Inline NOP helper to pad instructions
inline fn padNop3() void {
    asm volatile ("nop");
    asm volatile ("nop");
    asm volatile ("nop");
}

pub fn main() !void {
    print("==========================================================\n", .{});
    print(" EQUAL INSTRUCTION COUNT (8 INSTRS) N=30 BENCHMARK (M4)\n", .{});
    print("==========================================================\n\n", .{});

    var graph = crdt.SovraCrdtGraph.init();
    var rng_seed: u64 = 0x123456789ABCDEF0;

    // Warmup Pass
    var w: u64 = 0;
    while (w < 10000) : (w += 1) {
        _ = graph.insert_node(w + 1, .Episode, @as(u8, @intCast(w % 255)), 0);
    }
    graph.node_count = 0;

    const N_RUNS = 30;
    var interleaved_times: [N_RUNS]f64 = undefined;
    var decoupled_times: [N_RUNS]f64 = undefined;

    var volatile_checksum: u64 = 0;
    const volatile_ptr: *volatile u64 = &volatile_checksum;

    var r: usize = 0;
    while (r < N_RUNS) : (r += 1) {
        // ---------------------------------------------------------------------
        // LOOP A: INTERLEAVED LOOP (8 Instructions: str + immediate ldr STLF)
        // ---------------------------------------------------------------------
        graph.node_count = 0;
        rng_seed = 0x9876543210ABCDEF +% r;

        const t_a0 = getNanos();
        var i: u64 = 0;
        while (i < 100000) : (i += 1) {
            const dyn_payload = @as(u8, @intCast(nextRandom(&rng_seed) % 255));
            const ok = graph.insert_node(
                i + 1,
                if (dyn_payload % 2 == 0) .Episode else .Semantic,
                dyn_payload,
                if (i > 0) i else 0,
            );
            if (ok) {
                const node = graph.nodes[graph.node_count - 1]; // Interleaved immediate LDR
                const hash = @as(u64, node.confidence_byte) *% 1099511628211 +% node.version_vector;
                volatileWrite(volatile_ptr, volatile_ptr.* +% hash);
            }
        }
        const t_a1 = getNanos();
        interleaved_times[r] = @as(f64, @floatFromInt(t_a1 - t_a0)) / 100000.0;

        // ---------------------------------------------------------------------
        // LOOP B: NOP-PADDED DECOUPLED STORE LOOP (8 Instructions: str + 3 NOPs)
        // ---------------------------------------------------------------------
        graph.node_count = 0;
        rng_seed = 0x9876543210ABCDEF +% r;

        const t_b0 = getNanos();
        var j: u64 = 0;
        while (j < 100000) : (j += 1) {
            const dyn_payload = @as(u8, @intCast(nextRandom(&rng_seed) % 255));
            const ok = graph.insert_node(
                j + 1,
                if (dyn_payload % 2 == 0) .Episode else .Semantic,
                dyn_payload,
                if (j > 0) j else 0,
            );
            if (ok) {
                padNop3(); // Pad 3 NOPs replacing immediate ldr + hash multiply to match EXACT 8 instructions
                volatileWrite(volatile_ptr, volatile_ptr.* +% j);
            }
        }
        const t_b1 = getNanos();
        decoupled_times[r] = @as(f64, @floatFromInt(t_b1 - t_b0)) / 100000.0;
    }

    // Statistical Computations for N=30
    var mean_a: f64 = 0;
    var mean_b: f64 = 0;
    for (0..N_RUNS) |idx| {
        mean_a += interleaved_times[idx];
        mean_b += decoupled_times[idx];
    }
    mean_a /= @as(f64, @floatFromInt(N_RUNS));
    mean_b /= @as(f64, @floatFromInt(N_RUNS));

    var var_a: f64 = 0;
    var var_b: f64 = 0;
    for (0..N_RUNS) |idx| {
        var_a += (interleaved_times[idx] - mean_a) * (interleaved_times[idx] - mean_a);
        var_b += (decoupled_times[idx] - mean_b) * (decoupled_times[idx] - mean_b);
    }
    const std_a = std.math.sqrt(var_a / @as(f64, @floatFromInt(N_RUNS - 1)));
    const std_b = std.math.sqrt(var_b / @as(f64, @floatFromInt(N_RUNS - 1)));

    const se_a = std_a / std.math.sqrt(@as(f64, @floatFromInt(N_RUNS)));
    const se_b = std_b / std.math.sqrt(@as(f64, @floatFromInt(N_RUNS)));

    // t_0.025 for df=29 is 2.045
    const ci95_a = 2.045 * se_a;
    const ci95_b = 2.045 * se_b;

    const delta_ns = mean_a - mean_b;
    const delta_cycles = delta_ns * 3.8;

    print("--- [STATISTICAL TELEMETRY RESULTS (N=30 RUNS)] ---\n", .{});
    print("1. INTERLEAVED LOOP (STLF Forwarding): Mean = {d:.3} ns/op, StdDev = {d:.3} ns, 95% CI = [{d:.3}, {d:.3}] ns\n", .{ mean_a, std_a, mean_a - ci95_a, mean_a + ci95_a });
    print("   -> M4 Execution Throughput         : {d:.2} Gops/sec ({d:.2} M4 cycles/op)\n\n", .{ 1.0 / mean_a, mean_a * 3.8 });

    print("2. NOP-PADDED DECOUPLED LOOP (Equal 8 Instrs): Mean = {d:.3} ns/op, StdDev = {d:.3} ns, 95% CI = [{d:.3}, {d:.3}] ns\n", .{ mean_b, std_b, mean_b - ci95_b, mean_b + ci95_b });
    print("   -> M4 Execution Throughput         : {d:.2} Gops/sec ({d:.2} M4 cycles/op)\n\n", .{ 1.0 / mean_b, mean_b * 3.8 });

    print("3. ISOLATED STLF DEPENDENCY BUBBLE DELTA (Equal 8-Instruction Baseline):\n", .{});
    print("   -> Measured Delta                  : {d:.3} ns / op\n", .{delta_ns});
    print("   -> Isolated STLF Stall Cycles      : {d:.2} CPU cycles\n", .{delta_cycles});
    print("   -> Volatile Checksum (Consumed)    : {} (Blackbox Readback Proof)\n\n", .{volatile_checksum});

    print("==========================================================\n", .{});
}

