/*
 * 7TH LAYER CONSTANT-TIME NATIVE C IDENTITY GATE (Zero-Overhead Memory Map)
 * Target Hardware: Apple Silicon M4 Bare Metal (aarch64-apple-darwin)
 *
 * Performance Goal: Sub-100 nanosecond P99 latency at 2,000,000 node scale.
 * Memory Layout: Contiguous 64-byte L1-cache aligned slots.
 * Time Complexity: O(1) constant-time hash probe + constant-time 32-byte XOR validation.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define HASH_SIZE 32
#define SLOT_ALIGNMENT 64

typedef struct __attribute__((aligned(SLOT_ALIGNMENT))) {
    uint64_t agent_id_hash;
    uint8_t  expected_token[HASH_SIZE];
    uint8_t  occupied;
    uint8_t  padding[23]; // Fill to exactly 64 bytes (1 L1 cache line)
} IdentitySlot;

typedef struct {
    IdentitySlot* slots;
    uint64_t capacity;
    uint64_t mask;
    uint32_t num_shards;
} NativeIdentityGate;

// MurmurHash3 / FNV1a fast 64-bit hash for table slot indexing
static inline uint64_t fast_hash64(const char* str, size_t len) {
    uint64_t hash = 14695981039346656037ULL;
    for (size_t i = 0; i < len; i++) {
        hash ^= (uint64_t)str[i];
        hash *= 1099511628211ULL;
    }
    return hash;
}

// Constant-time 32-byte equality check (prevents timing side-channels)
static inline int constant_time_memcmp_32(const uint8_t* a, const uint8_t* b) {
    uint8_t diff = 0;
    for (int i = 0; i < 32; i++) {
        diff |= (a[i] ^ b[i]);
    }
    return diff == 0;
}

NativeIdentityGate* native_gate_init(uint64_t min_capacity) {
    // Round capacity to next power of 2 for fast bitwise AND indexing
    uint64_t cap = 1;
    while (cap < (min_capacity * 2)) {
        cap <<= 1;
    }

    NativeIdentityGate* gate = (NativeIdentityGate*)malloc(sizeof(NativeIdentityGate));
    gate->capacity = cap;
    gate->mask = cap - 1;
    gate->num_shards = 16;

    // Allocate aligned memory (64-byte boundaries for M4 L1 cache lines)
    if (posix_memalign((void**)&gate->slots, SLOT_ALIGNMENT, cap * sizeof(IdentitySlot)) != 0) {
        free(gate);
        return NULL;
    }
    memset(gate->slots, 0, cap * sizeof(IdentitySlot));
    return gate;
}

void native_gate_insert(NativeIdentityGate* gate, const char* agent_id, const uint8_t* token_32) {
    uint64_t id_hash = fast_hash64(agent_id, strlen(agent_id));
    uint64_t idx = id_hash & gate->mask;

    // Open addressing linear probe
    while (gate->slots[idx].occupied) {
        if (gate->slots[idx].agent_id_hash == id_hash) {
            break; // Overwrite existing
        }
        idx = (idx + 1) & gate->mask;
    }

    gate->slots[idx].agent_id_hash = id_hash;
    memcpy(gate->slots[idx].expected_token, token_32, HASH_SIZE);
    gate->slots[idx].occupied = 1;
}

// THE GATE: Constant-time probe & check
// Returns 1 (PASS) or 0 (KILL)
int native_gate_check(const NativeIdentityGate* gate, const char* agent_id, const uint8_t* presented_token_32) {
    uint64_t id_hash = fast_hash64(agent_id, strlen(agent_id));
    uint64_t idx = id_hash & gate->mask;

    // Fast linear probe inside L1/L2 cache
    while (gate->slots[idx].occupied) {
        if (gate->slots[idx].agent_id_hash == id_hash) {
            return constant_time_memcmp_32(gate->slots[idx].expected_token, presented_token_32);
        }
        idx = (idx + 1) & gate->mask;
    }
    return 0; // Not found -> KILL
}

void native_gate_free(NativeIdentityGate* gate) {
    if (gate) {
        if (gate->slots) free(gate->slots);
        free(gate);
    }
}

#include "native_identity_gate.c"
#include <stdio.h>
#include <time.h>

#define N_CHECKS 100000

static inline double get_ns(struct timespec start, struct timespec end) {
    return (double)(end.tv_sec - start.tv_sec) * 1e9 + (double)(end.tv_nsec - start.tv_nsec);
}

void run_benchmark_for_scale(uint64_t num_agents) {
    printf("\n--- Native Scale: %llu agents ---\n", (unsigned long long)num_agents);

    struct timespec t_start, t_end;
    clock_gettime(CLOCK_MONOTONIC, &t_start);
    NativeIdentityGate* gate = native_gate_init(num_agents);
    clock_gettime(CLOCK_MONOTONIC, &t_end);
    double init_ms = get_ns(t_start, t_end) / 1e6;

    // Generate keys and populate
    uint8_t dummy_token[32];
    memset(dummy_token, 0xAB, 32);

    clock_gettime(CLOCK_MONOTONIC, &t_start);
    char agent_id[64];
    for (uint64_t i = 0; i < num_agents; i++) {
        snprintf(agent_id, sizeof(agent_id), "agent_%llu", (unsigned long long)i);
        dummy_token[0] = (uint8_t)(i & 0xFF);
        native_gate_insert(gate, agent_id, dummy_token);
    }
    clock_gettime(CLOCK_MONOTONIC, &t_end);
    double insert_ms = get_ns(t_start, t_end) / 1e6;

    // Run N_CHECKS lookup benchmarks
    double* latencies = (double*)malloc(N_CHECKS * sizeof(double));
    int pass_count = 0;

    for (int i = 0; i < N_CHECKS; i++) {
        uint64_t target_id = (i * 17) % num_agents; // Pseudo-random probe distribution
        snprintf(agent_id, sizeof(agent_id), "agent_%llu", (unsigned long long)target_id);
        dummy_token[0] = (uint8_t)(target_id & 0xFF);

        clock_gettime(CLOCK_MONOTONIC, &t_start);
        int res = native_gate_check(gate, agent_id, dummy_token);
        clock_gettime(CLOCK_MONOTONIC, &t_end);

        latencies[i] = get_ns(t_start, t_end);
        if (res) pass_count++;
    }

    // Sort latencies for percentiles
    for (int i = 0; i < N_CHECKS - 1; i++) {
        for (int j = i + 1; j < N_CHECKS; j++) {
            if (latencies[i] > latencies[j]) {
                double tmp = latencies[i];
                latencies[i] = latencies[j];
                latencies[j] = tmp;
            }
        }
    }

    double sum = 0;
    for (int i = 0; i < N_CHECKS; i++) sum += latencies[i];
    double avg = sum / N_CHECKS;
    double p50 = latencies[N_CHECKS / 2];
    double p99 = latencies[(int)(N_CHECKS * 0.99)];
    double p999 = latencies[(int)(N_CHECKS * 0.999)];

    printf("  Init Time      : %.2f ms\n", init_ms);
    printf("  Insert Time    : %.2f ms\n", insert_ms);
    printf("  Gate Checks    : %d (Passed: %d)\n", N_CHECKS, pass_count);
    printf("  Avg Latency    : %.1f ns (%.3f us)\n", avg, avg / 1000.0);
    printf("  P50            : %.1f ns\n", p50);
    printf("  P99            : %.1f ns (%.3f us)\n", p99, p99 / 1000.0);
    printf("  P99.9          : %.1f ns\n", p999);
    printf("  Sub-100ns SLO  : %s\n", (p99 < 100.0) ? "✅ PASSED" : "❌ FAILED");

    free(latencies);
    native_gate_free(gate);
}

int main() {
    printf("======================================================================\n");
    printf("  XORAS 7TH LAYER NATIVE C CONSTANT-TIME GATE BENCHMARK (M4 SILICON)\n");
    printf("  Memory Layout: 64-byte Cache-Aligned Slots | Zero OS Allocations\n");
    printf("======================================================================\n");

    run_benchmark_for_scale(1000);
    run_benchmark_for_scale(65536);
    run_benchmark_for_scale(500000);
    run_benchmark_for_scale(2000000);

    printf("======================================================================\n");
    return 0;
}

