#define SLOT_SIZE 128

typedef struct {
    uint8_t prepare_vote; // 0=none, 1=false, 2=true
    uint8_t commit_vote;  // 0=none, 1=false, 2=true
    uint8_t final_vote;   // 0=none, 1=false, 2=true
    uint8_t pad[125];
} NodeSlot;

typedef struct {
    uint64_t num_nodes;
    uint64_t num_byzantine;
    uint64_t honest_quorum;
    NodeSlot* slots;
} BftSwarm;

static mach_timebase_info_data_t timebase_info;

static inline double ticks_to_ms(uint64_t ticks) {
    return (double)ticks * (double)timebase_info.numer / ((double)timebase_info.denom * 1e6);
}

// Multithreaded state update worker
typedef struct {
    BftSwarm* swarm;
    uint64_t start_idx;
    uint64_t end_idx;
    uint8_t proposal_value;
    int phase; // 1=prepare, 2=commit, 3=finalize
} WorkerArgs;

void* bft_phase_worker(void* arg) {
    WorkerArgs* w = (WorkerArgs*)arg;
    BftSwarm* swarm = w->swarm;
    uint8_t prop = w->proposal_value;

    for (uint64_t i = w->start_idx; i < w->end_idx; i++) {
        int is_byzantine = (i < swarm->num_byzantine);
        if (w->phase == 1) {
            // Prepare Phase
            uint8_t vote = is_byzantine ? (!prop ? 2 : 1) : (prop ? 2 : 1);
            swarm->slots[i].prepare_vote = vote;
        } else if (w->phase == 2) {
            // Commit Phase
            uint8_t vote = is_byzantine ? (!prop ? 2 : 1) : (prop ? 2 : 1);
            swarm->slots[i].commit_vote = vote;
        } else if (w->phase == 3) {
            // Finalization Phase
            if (!is_byzantine) {
                swarm->slots[i].final_vote = prop ? 2 : 1;
            }
        }
    }
    return NULL;
}

void run_parallel_phase(BftSwarm* swarm, uint8_t proposal_value, int phase, int num_threads) {
    pthread_t threads[num_threads];
    WorkerArgs args[num_threads];
    uint64_t chunk = swarm->num_nodes / num_threads;

    for (int t = 0; t < num_threads; t++) {
        args[t].swarm = swarm;
        args[t].start_idx = t * chunk;
        args[t].end_idx = (t == num_threads - 1) ? swarm->num_nodes : (t + 1) * chunk;
        args[t].proposal_value = proposal_value;
        args[t].phase = phase;
        pthread_create(&threads[t], NULL, bft_phase_worker, &args[t]);
    }

    for (int t = 0; t < num_threads; t++) {
        pthread_join(threads[t], NULL);
    }
}

