} WorkerArgs;

void* breaking_worker(void* arg) {
    WorkerArgs* w = (WorkerArgs*)arg;
    BreakingSwarm* s = w->swarm;
    uint8_t prop = w->prop;
    uint64_t byz_cutoff = s->num_byzantine;
    uint64_t start = w->start_idx;
    uint64_t end = w->end_idx;
    NodeState* states = s->states;

    if (w->phase == 1) {
        for (uint64_t i = start; i < end; i++) {
            uint8_t is_byz = (i < byz_cutoff) ? 1 : 0;
            uint8_t vote = is_byz ? (prop == 2 ? 1 : 2) : prop;
            states[i] = (states[i] & 0xFC) | (vote & 0x03) | (is_byz << 6);
        }
    } else if (w->phase == 2) {
        for (uint64_t i = start; i < end; i++) {
            uint8_t is_byz = (states[i] >> 6) & 1;
            uint8_t vote = is_byz ? (prop == 2 ? 1 : 2) : prop;
            states[i] = (states[i] & 0xF3) | ((vote & 0x03) << 2);
        }
    } else if (w->phase == 3) {
        uint64_t count = 0;
        for (uint64_t i = start; i < end; i++) {
            uint8_t is_byz = (states[i] >> 6) & 1;
            if (!is_byz) {
                states[i] = (states[i] & 0xCF) | ((prop & 0x03) << 4);
                if (((states[i] >> 4) & 0x03) == prop) count++;
            }
        }
        w->local_agreed = count;
    }
    return NULL;
}

void run_breaking_phase(BreakingSwarm* s, uint8_t prop, int phase, int threads, uint64_t* honest_agreed_out) {
    pthread_t th[threads];
    WorkerArgs args[threads];
    uint64_t chunk = s->num_nodes / threads;

    for (int t = 0; t < threads; t++) {
        args[t].swarm = s;
        args[t].start_idx = t * chunk;
        args[t].end_idx = (t == threads - 1) ? s->num_nodes : (t + 1) * chunk;
        args[t].prop = prop;
        args[t].phase = phase;
        args[t].local_agreed = 0;
        pthread_create(&th[t], NULL, breaking_worker, &args[t]);
    }

    uint64_t total = 0;
    for (int t = 0; t < threads; t++) {
        pthread_join(th[t], NULL);
        total += args[t].local_agreed;
    }
    if (honest_agreed_out) *honest_agreed_out = total;
}

