}

// 2-bit state packing helpers:
// Node i state is stored in byte (i / 4), bits ((i % 4) * 2) .. ((i % 4) * 2 + 1)
// State codes: 00 = IDLE, 01 = FALSE_VOTE, 10 = TRUE_VOTE, 11 = BYZANTINE
static inline void set_node_state(uint8_t* bitset, uint64_t node_idx, uint8_t state_2bit) {
    uint64_t byte_idx = node_idx >> 2;
    uint8_t bit_shift = (node_idx & 3) << 1;
    uint8_t mask = ~(3 << bit_shift);
    bitset[byte_idx] = (bitset[byte_idx] & mask) | ((state_2bit & 3) << bit_shift);
}

static inline uint8_t get_node_state(const uint8_t* bitset, uint64_t node_idx) {
    uint64_t byte_idx = node_idx >> 2;
    uint8_t bit_shift = (node_idx & 3) << 1;
    return (bitset[byte_idx] >> bit_shift) & 3;
}

// Leaf Shard Reduction Worker
typedef struct {
    BitpackedSwarm* swarm;
    uint64_t start_node;
    uint64_t end_node;
    uint8_t proposal_val;
    int phase;
    uint64_t local_honest_agreed;
} ShardWorkerArgs;

void* tree_shard_worker(void* arg) {
    ShardWorkerArgs* w = (ShardWorkerArgs*)arg;
    BitpackedSwarm* s = w->swarm;
    uint8_t prop = w->proposal_val; // 2 = True, 1 = False
    uint64_t byz_cutoff = s->num_byzantine;
    uint8_t* bitset = s->bitset;
    uint64_t start = w->start_node;
    uint64_t end = w->end_node;

    if (w->phase == 1) {
        // PREPARE PHASE: Bit-Packed SIMD Loop
        for (uint64_t i = start; i < end; i++) {
            uint8_t is_byz = (i < byz_cutoff) ? 1 : 0;
            uint8_t vote = is_byz ? (prop == 2 ? 1 : 2) : prop;
            set_node_state(bitset, i, vote);
        }
    } else if (w->phase == 2) {
        // COMMIT PHASE
        for (uint64_t i = start; i < end; i++) {
            uint8_t is_byz = (i < byz_cutoff) ? 1 : 0;
            uint8_t vote = is_byz ? (prop == 2 ? 1 : 2) : prop;
            set_node_state(bitset, i, vote);
        }
    } else if (w->phase == 3) {
        // HIERARCHICAL TREE REDUCTION PHASE (Local Leaf Quorum Summary)
        uint64_t local_count = 0;
        for (uint64_t i = start; i < end; i++) {
            if (i >= byz_cutoff) { // Honest node
                uint8_t state = get_node_state(bitset, i);
                if (state == prop) {
                    local_count++;
                }
            }
        }
        w->local_honest_agreed = local_count;
    }
    return NULL;
}

void run_hierarchical_phase(BitpackedSwarm* s, uint8_t prop, int phase, int threads, uint64_t* total_agreed_out) {
    pthread_t th[threads];
    ShardWorkerArgs args[threads];
    uint64_t chunk = s->num_nodes / threads;

    for (int t = 0; t < threads; t++) {
        args[t].swarm = s;
        args[t].start_node = t * chunk;
        args[t].end_node = (t == threads - 1) ? s->num_nodes : (t + 1) * chunk;
        args[t].proposal_val = prop;
        args[t].phase = phase;
        args[t].local_honest_agreed = 0;
        pthread_create(&th[t], NULL, tree_shard_worker, &args[t]);
    }

    uint64_t total_leaf_quorum = 0;
    for (int t = 0; t < threads; t++) {
        pthread_join(th[t], NULL);
        total_leaf_quorum += args[t].local_honest_agreed;
    }

    if (total_agreed_out) {
        *total_agreed_out = total_leaf_quorum;
    }
}

