#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <mach/mach_time.h>
#include <pthread.h>
#include <arm_neon.h>

#define BITS_PER_NODE 2
#define NODES_PER_UINT64 32 // 64 bits / 2 bits = 32 nodes per 64-bit word

typedef struct {
    uint64_t num_nodes;
    uint64_t num_byzantine;
    uint64_t honest_quorum;
    uint64_t word_capacity;
    uint64_t* word_array;
} HyperSwarm;

static mach_timebase_info_data_t timebase_info;

static inline double ticks_to_ms(uint64_t t) {
    return (double)t * (double)timebase_info.numer / ((double)timebase_info.denom * 1e6);
}

// 2-bit state mapping: 00=IDLE, 01=FALSE_VOTE, 10=TRUE_VOTE, 11=BYZANTINE
static inline void set_bitmatrix_node(uint64_t* words, uint64_t idx, uint8_t state) {
    uint64_t word_idx = idx / NODES_PER_UINT64;
    uint8_t shift = (idx % NODES_PER_UINT64) * BITS_PER_NODE;
    uint64_t mask = ~(3ULL << shift);
    words[word_idx] = (words[word_idx] & mask) | (((uint64_t)(state & 3)) << shift);
}

static inline uint8_t get_bitmatrix_node(const uint64_t* words, uint64_t idx) {
    uint64_t word_idx = idx / NODES_PER_UINT64;
    uint8_t shift = (idx % NODES_PER_UINT64) * BITS_PER_NODE;
    return (words[word_idx] >> shift) & 3;
}

// Fast SIMD Vector Population Count for True Votes (State == 2)
static inline uint64_t neon_popcount_true_votes(const uint64_t* words, uint64_t word_count) {
    uint64_t total_true = 0;
    uint64_t i = 0;

    // Process 2 uint64 words (64 nodes) per NEON vector iteration
    for (; i + 1 < word_count; i += 2) {
        uint64x2_t raw_val = vld1q_u64(&words[i]);
        uint8x16_t vec_u8 = vreinterpretq_u8_u64(raw_val);

        // Mask out odd bits (vote bit 1)
        uint8x16_t true_bits = vandq_u8(vec_u8, vdupq_n_u8(0xAA));
        // Shift right by 1 and count matching 10 states
        uint8x16_t popcnt = vcntq_u8(vshrq_n_u8(true_bits, 1));
        uint16x8_t sum16 = vpaddlq_u8(popcnt);
        uint32x4_t sum32 = vpaddlq_u16(sum16);
        uint64x2_t sum64 = vpaddlq_u32(sum32);

        total_true += vaddvq_u64(sum64);
    }

    // Process remainder
    for (; i < word_count; i++) {
        uint64_t w = words[i];
        for (int k = 0; k < 32; k++) {
            if (((w >> (k * 2)) & 3) == 2) {
                total_true++;
            }
        }
    }
    return total_true;
}

typedef struct {
    HyperSwarm* swarm;
    uint64_t start_node;
