} HyperWorkerArgs;

void* hyper_tree_worker(void* arg) {
    HyperWorkerArgs* w = (HyperWorkerArgs*)arg;
    HyperSwarm* s = w->swarm;
    uint8_t prop = w->prop_val;
    uint64_t byz_cutoff = s->num_byzantine;
    uint64_t* words = s->word_array;
    uint64_t start = w->start_node;
