    } else if (w->phase == 3) {
        // HIERARCHICAL 3-TIER SIMD LEAF REDUCTION PHASE
        uint64_t honest_start = (start < byz_cutoff) ? byz_cutoff : start;
        uint64_t honest_end = end;
        uint64_t local_agreed = 0;

        if (honest_start < honest_end) {
            uint64_t start_word = honest_start / NODES_PER_UINT64;
            uint64_t end_word = honest_end / NODES_PER_UINT64;
            uint64_t word_cnt = (end_word > start_word) ? (end_word - start_word) : 0;

            if (word_cnt > 0) {
                local_agreed = neon_popcount_true_votes(&words[start_word], word_cnt);
            } else {
                for (uint64_t i = honest_start; i < honest_end; i++) {
                    if (get_bitmatrix_node(words, i) == prop) {
                        local_agreed++;
                    }
                }
            }
        }
        w->local_honest_agreed = local_agreed;
    }
    return NULL;
}

void run_hyper_tree_phase(HyperSwarm* s, uint8_t prop, int phase, int threads, uint64_t* honest_agreed_out) {
