)

func go18432dDot(a []float32, b []float32) float32 {
	var sum0, sum1, sum2, sum3 float32
	for i := 0; i < DIM; i += 4 {
		sum0 += a[i] * b[i]
		sum1 += a[i+1] * b[i+1]
		sum2 += a[i+2] * b[i+2]
		sum3 += a[i+3] * b[i+3]
	}
	return sum0 + sum1 + sum2 + sum3
}

type BenchResult struct {
	Language       string  `json:"language"`
	ElapsedMs      float64 `json:"elapsed_ms"`
	EvalsPerSec    float64 `json:"evals_per_sec"`
	Gflops         float64 `json:"gflops"`
	BandwidthGbSec float64 `json:"bandwidth_gb_sec"`
	P50Us          float64 `json:"p50_us"`
	P90Us          float64 `json:"p90_us"`
	P99Us          float64 `json:"p99_us"`
}

func main() {
	query := make([]float32, DIM)
	for i := 0; i < DIM; i++ {
		query[i] = float32(i%100) * 0.001
	}

	matrix := make([]float32, TOTAL_VECTORS*DIM)
	for i := 0; i < TOTAL_VECTORS*DIM; i++ {
		matrix[i] = float32((i+1)%100) * 0.001
	}

	latencies := make([]float64, TOTAL_VECTORS)
	vecsPerRoutine := TOTAL_VECTORS / NUM_CORES

	var wg sync.WaitGroup
	tStart := time.Now()

	for t := 0; t < NUM_CORES; t++ {
		wg.Add(1)
		startIdx := t * vecsPerRoutine
		count := vecsPerRoutine
		if t == NUM_CORES-1 {
			count = TOTAL_VECTORS - startIdx
		}

		go func(start, cnt int) {
			defer wg.Done()
			for i := 0; i < cnt; i++ {
				vecIdx := start + i
				s0 := time.Now()
				_ = go18432dDot(query, matrix[vecIdx*DIM:(vecIdx+1)*DIM])
				latencies[vecIdx] = float64(time.Since(s0).Nanoseconds()) / 1000.0
			}
		}(startIdx, count)
	}

	wg.Wait()
	elapsedSec := time.Since(tStart).Seconds()
	elapsedMs := elapsedSec * 1000.0

	evalsPerSec := float64(TOTAL_VECTORS) / elapsedSec
	gflops := (float64(TOTAL_VECTORS) * float64(DIM) * 2.0) / (elapsedSec * 1e9)
	gbSec := ((float64(TOTAL_VECTORS) * float64(DIM) * 4.0) / (1024.0 * 1024.0 * 1024.0)) / elapsedSec

	sort.Float64s(latencies)
	p50 := latencies[int(float64(TOTAL_VECTORS)*0.50)]
	p90 := latencies[int(float64(TOTAL_VECTORS)*0.90)]
	p99 := latencies[int(float64(TOTAL_VECTORS)*0.99)]

