//! Sovereign 18,432-Dimensional Hexological Vectoring Engine (Rust 1.95+)
//! Substrate: Apple Silicon M4 Bare Metal (10 CPU Cores, Rayon Multithreading)

use chrono::Utc;
use rayon::prelude::*;
use serde::Serialize;
use std::env;
use std::fs::File;
use std::io::Write;
use std::time::Instant;

const DIM: usize = 18432;
const TOTAL_VECTORS: usize = 100_000;

#[derive(Serialize)]
struct AuditReport {
    language: String,
    elapsed_ms: f64,
    evals_per_sec: f64,
    gflops: f64,
    bandwidth_gb_sec: f64,
    p50_us: f64,
    p90_us: f64,
    p99_us: f64,
}

#[inline(always)]
fn hexological_18432d_dot_product(a: &[f32], b: &[f32]) -> f32 {
    debug_assert_eq!(a.len(), DIM);
    debug_assert_eq!(b.len(), DIM);

    let mut sum0 = 0.0f32;
    let mut sum1 = 0.0f32;
    let mut sum2 = 0.0f32;
    let mut sum3 = 0.0f32;

    let chunks_a = a.chunks_exact(4);
    let chunks_b = b.chunks_exact(4);

    for (ca, cb) in chunks_a.zip(chunks_b) {
        sum0 += ca[0] * cb[0];
        sum1 += ca[1] * cb[1];
        sum2 += ca[2] * cb[2];
        sum3 += ca[3] * cb[3];
    }

    sum0 + sum1 + sum2 + sum3
}

fn main() {
    let json_mode = env::args().any(|arg| arg == "--json");

    let query_vec: Vec<f32> = (0..DIM).map(|i| (i % 100) as f32 * 0.001).collect();
    let target_matrix: Vec<f32> = (0..(TOTAL_VECTORS * DIM))
        .map(|i| ((i + 1) % 100) as f32 * 0.001)
        .collect();

    let t_start = Instant::now();

    let mut latencies: Vec<f64> = target_matrix
        .par_chunks_exact(DIM)
        .map(|target_node| {
            let t0 = Instant::now();
            let _dot = hexological_18432d_dot_product(&query_vec, target_node);
            t0.elapsed().as_secs_f64() * 1e6
        })
        .collect();

    let total_elapsed = t_start.elapsed();
    let elapsed_ms = total_elapsed.as_secs_f64() * 1000.0;
    let elapsed_sec = total_elapsed.as_secs_f64();

    let evals_per_sec = TOTAL_VECTORS as f64 / elapsed_sec;
    let gflops = (TOTAL_VECTORS as f64 * DIM as f64 * 2.0) / (elapsed_sec * 1e9);
    let bytes_gb = (TOTAL_VECTORS as f64 * DIM as f64 * 4.0) / (1024.0 * 1024.0 * 1024.0);
    let bandwidth_gb_sec = bytes_gb / elapsed_sec;

    latencies.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let p50 = latencies[(TOTAL_VECTORS as f64 * 0.50) as usize];
    let p90 = latencies[(TOTAL_VECTORS as f64 * 0.90) as usize];
    let p99 = latencies[(TOTAL_VECTORS as f64 * 0.99) as usize];

    let report = AuditReport {
        language: "Rust 1.95 (Cargo + Rayon)".to_string(),
        elapsed_ms,
        evals_per_sec,
        gflops,
        bandwidth_gb_sec,
        p50_us: p50,
        p90_us: p90,
        p99_us: p99,
    };

    let report_json = serde_json::to_string_pretty(&report).unwrap();

    if json_mode {
        println!("{}", report_json);
    } else {
        println!("======================================================================");
        println!("  XORAS SOVEREIGN RUST 18,432-DIMENSIONAL HEXOLOGICAL VECTOR ENGINE");
        println!("  Target Architecture: Apple Silicon M4 Bare Metal (10 Cores | Rayon)");
        println!("  Language Engine    : Pure Sovereign Rust 1.95+");
        println!("======================================================================\n");
        println!("⚡ Allocating {} 18,432-D Hexological Memory Nodes ({:.2} GB Vector Data)...", TOTAL_VECTORS, bytes_gb);
        println!("🔥 Executing 10-Core Parallel 18,432-D SIMD Vectorization Engine in Rust...\n");
        println!("{}", report_json);

        let report_path = "/Users/ajoxendine68/Desktop/SSOT_Agentic_Brain/docs/audits/SOVEREIGN_RUST_18432D_AUDIT.json";
        if let Ok(mut file) = File::create(report_path) {
            let _ = file.write_all(report_json.as_bytes());
        }
    }
}

