// Ground-Truth DRAM Memory Streaming Bandwidth Baseline for Apple Silicon M4
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <mach/mach_time.h>
#include <arm_neon.h>

#define DIM 18432
#define TOTAL_VECTORS 100000
#define NUM_CORES 10
#define ITERATIONS 20

static double get_time_sec(void) {
    static mach_timebase_info_data_t timebase;
    if (timebase.denom == 0) {
        mach_timebase_info(&timebase);
    }
    uint64_t time = mach_absolute_time();
    return (double)time * timebase.numer / timebase.denom / 1e9;
}

typedef struct {
    const float *src;
    float *dst;
    size_t count;
} CopyTask;

static void *copy_worker(void *arg) {
    CopyTask *task = (CopyTask *)arg;
    size_t num_bytes = task->count * sizeof(float);
    memcpy(task->dst, task->src, num_bytes);
    return NULL;
}

int main(void) {
    size_t total_floats = (size_t)TOTAL_VECTORS * DIM;
    size_t total_bytes = total_floats * sizeof(float);

    float *src = (float *)aligned_alloc(64, total_bytes);
    float *dst = (float *)aligned_alloc(64, total_bytes);

    for (size_t i = 0; i < total_floats; i++) {
        src[i] = (float)(i % 100) * 0.001f;
    }

    // Warmup pass
    for (int iter = 0; iter < 5; iter++) {
        memcpy(dst, src, total_bytes);
    }

    pthread_t threads[NUM_CORES];
    CopyTask tasks[NUM_CORES];
    size_t floats_per_core = total_floats / NUM_CORES;

    double t0 = get_time_sec();
    for (int iter = 0; iter < ITERATIONS; iter++) {
        for (int t = 0; t < NUM_CORES; t++) {
            tasks[t].src = src + t * floats_per_core;
            tasks[t].dst = dst + t * floats_per_core;
            tasks[t].count = (t == NUM_CORES - 1) ? (total_floats - t * floats_per_core) : floats_per_core;
            pthread_create(&threads[t], NULL, copy_worker, &tasks[t]);
        }
        for (int t = 0; t < NUM_CORES; t++) {
            pthread_join(threads[t], NULL);
        }
    }
    double total_time = get_time_sec() - t0;
    double avg_time_per_pass = total_time / ITERATIONS;

    // Each pass reads total_bytes and writes total_bytes = 2x memory traffic
    double total_gigabytes_transferred = (double)(total_bytes * 2) / (1024.0 * 1024.0 * 1024.0);
    double bandwidth_gb_sec = total_gigabytes_transferred / avg_time_per_pass;

    printf("{\n");
    printf("  \"benchmark\": \"M4 LPDDR5X Hardware STREAM Baseline\",\n");
    printf("  \"total_dataset_gb\": %.4f,\n", (double)total_bytes / (1024.0 * 1024.0 * 1024.0));
    printf("  \"avg_pass_ms\": %.2f,\n", avg_time_per_pass * 1000.0);
    printf("  \"effective_dram_bandwidth_gb_sec\": %.2f\n", bandwidth_gb_sec);
    printf("}\n");

    free(src);
    free(dst);
    return 0;
}

// Calibrated C++20 18,432-D Hexological Vector Engine Benchmark
// Substrate: Apple Silicon M4 Bare Metal (ARM NEON, Multi-Threaded)

#include <iostream>
#include <vector>
#include <chrono>
#include <numeric>
#include <algorithm>
#include <thread>
#include <atomic>
#include <cmath>
#include <arm_neon.h>

constexpr size_t DIM = 18432;
constexpr size_t TOTAL_VECTORS = 100000;
constexpr size_t NUM_CORES = 10;
constexpr size_t ITERATIONS = 20;

std::atomic<double> g_volatile_sink{0.0};

inline float cpp_18432d_dot(const float* a, const float* b) {
    float32x4_t acc0 = vdupq_n_f32(0.0f);
    float32x4_t acc1 = vdupq_n_f32(0.0f);

    for (size_t i = 0; i < DIM; i += 8) {
        float32x4_t va0 = vld1q_f32(a + i);
        float32x4_t vb0 = vld1q_f32(b + i);
        acc0 = vmlaq_f32(acc0, va0, vb0);

        float32x4_t va1 = vld1q_f32(a + i + 4);
        float32x4_t vb1 = vld1q_f32(b + i + 4);
        acc1 = vmlaq_f32(acc1, va1, vb1);
    }
    float32x4_t sum = vaddq_f32(acc0, acc1);
    return vaddvq_f32(sum);
}

int main() {
    std::vector<float> query(DIM);
    for (size_t i = 0; i < DIM; ++i) query[i] = (i % 100) * 0.001f;

    std::vector<float> matrix(TOTAL_VECTORS * DIM);
    for (size_t i = 0; i < TOTAL_VECTORS * DIM; ++i) matrix[i] = ((i + 1) % 100) * 0.001f;

    size_t vecs_per_thread = TOTAL_VECTORS / NUM_CORES;

    // 1. Warmup Pass (10 passes)
    for (size_t warm = 0; warm < 10; ++warm) {
        std::vector<std::thread> warm_threads;
        for (size_t t = 0; t < NUM_CORES; ++t) {
            size_t start_idx = t * vecs_per_thread;
            size_t count = (t == NUM_CORES - 1) ? (TOTAL_VECTORS - start_idx) : vecs_per_thread;
            warm_threads.emplace_back([&query, &matrix, start_idx, count]() {
                float local_sum = 0.0f;
                for (size_t i = 0; i < count; ++i) {
                    size_t vec_idx = start_idx + i;
                    local_sum += cpp_18432d_dot(query.data(), matrix.data() + (vec_idx * DIM));
                }
                g_volatile_sink.fetch_add(local_sum, std::memory_order_relaxed);
            });
        }
        for (auto& th : warm_threads) th.join();
    }

    // 2. Timed Iterations
    std::vector<double> sample_latencies_ms;
    sample_latencies_ms.reserve(ITERATIONS);

    double total_accumulated_sum = 0.0;
    auto t_start = std::chrono::high_resolution_clock::now();

    for (size_t iter = 0; iter < ITERATIONS; ++iter) {
        auto iter_start = std::chrono::high_resolution_clock::now();

        std::vector<std::thread> threads;
        std::vector<double> thread_sums(NUM_CORES, 0.0);

        for (size_t t = 0; t < NUM_CORES; ++t) {
            size_t start_idx = t * vecs_per_thread;
            size_t count = (t == NUM_CORES - 1) ? (TOTAL_VECTORS - start_idx) : vecs_per_thread;
            threads.emplace_back([&query, &matrix, &thread_sums, t, start_idx, count]() {
                double local_sum = 0.0;
                for (size_t i = 0; i < count; ++i) {
                    size_t vec_idx = start_idx + i;
                    local_sum += cpp_18432d_dot(query.data(), matrix.data() + (vec_idx * DIM));
                }
                thread_sums[t] = local_sum;
            });
        }

        for (auto& th : threads) th.join();

        for (double s : thread_sums) total_accumulated_sum += s;

        auto iter_end = std::chrono::high_resolution_clock::now();
        double iter_ms = std::chrono::duration<double, std::milli>(iter_end - iter_start).count();
        sample_latencies_ms.push_back(iter_ms);
    }

    auto t_end = std::chrono::high_resolution_clock::now();
    g_volatile_sink.fetch_add(total_accumulated_sum, std::memory_order_relaxed);

    double total_elapsed_ms = std::chrono::duration<double, std::milli>(t_end - t_start).count();
    double avg_pass_ms = total_elapsed_ms / ITERATIONS;
    double avg_pass_sec = avg_pass_ms / 1000.0;

    double evals_per_sec = TOTAL_VECTORS / avg_pass_sec;
    double gflops = (TOTAL_VECTORS * DIM * 2.0) / (avg_pass_sec * 1e9);
    double gb_sec = ((TOTAL_VECTORS * DIM * 4.0) / (1024.0 * 1024.0 * 1024.0)) / avg_pass_sec;

    std::sort(sample_latencies_ms.begin(), sample_latencies_ms.end());
    double p50_pass_ms = sample_latencies_ms[ITERATIONS * 0.50];
    double p90_pass_ms = sample_latencies_ms[ITERATIONS * 0.90];
    double p99_pass_ms = sample_latencies_ms[ITERATIONS * 0.99];

    // Per-vector latencies in microseconds
    double p50_vec_us = (p50_pass_ms * 1000.0) / TOTAL_VECTORS;
    double p90_vec_us = (p90_pass_ms * 1000.0) / TOTAL_VECTORS;
    double p99_vec_us = (p99_pass_ms * 1000.0) / TOTAL_VECTORS;

    std::cout << "{\n"
              << "  \"language\": \"C++20 (clang++ -O3)\",\n"
              << "  \"avg_pass_ms\": " << avg_pass_ms << ",\n"
              << "  \"evals_per_sec\": " << evals_per_sec << ",\n"
              << "  \"gflops\": " << gflops << ",\n"
              << "  \"bandwidth_gb_sec\": " << gb_sec << ",\n"
              << "  \"p50_us\": " << p50_vec_us << ",\n"
              << "  \"p90_us\": " << p90_vec_us << ",\n"
              << "  \"p99_us\": " << p99_vec_us << ",\n"
              << "  \"sink_check\": " << g_volatile_sink.load() << "\n"
              << "}\n";

    return 0;
}

// Calibrated SOVRA C/NEON 18,432-D Hexological Vector Engine Benchmark
// Substrate: Apple Silicon M4 Bare Metal (10 CPU Cores / ARM64 NEON SIMD FMA)

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <arm_neon.h>
#include <mach/mach_time.h>

#define DIM 18432
#define TOTAL_VECTORS 100000
#define NUM_CORES 10
#define ITERATIONS 20

static volatile double g_volatile_sink = 0.0;

static double get_time_sec(void) {
    static mach_timebase_info_data_t timebase;
    if (timebase.denom == 0) {
        mach_timebase_info(&timebase);
    }
    uint64_t time = mach_absolute_time();
    return (double)time * timebase.numer / timebase.denom / 1e9;
}

static inline float sovra_18432d_dot(const float *a, const float *b) {
    float32x4_t acc0 = vdupq_n_f32(0.0f);
    float32x4_t acc1 = vdupq_n_f32(0.0f);

    for (int i = 0; i < DIM; i += 8) {
        float32x4_t va0 = vld1q_f32(a + i);
        float32x4_t vb0 = vld1q_f32(b + i);
        acc0 = vmlaq_f32(acc0, va0, vb0);

        float32x4_t va1 = vld1q_f32(a + i + 4);
        float32x4_t vb1 = vld1q_f32(b + i + 4);
        acc1 = vmlaq_f32(acc1, va1, vb1);
    }
    float32x4_t sum = vaddq_f32(acc0, acc1);
    return vaddvq_f32(sum);
}

typedef struct {
    const float *query;
    const float *matrix;
    uint32_t start_idx;
    uint32_t count;
    double local_sum;
} WorkerTask;

static void *sovra_worker(void *arg) {
    WorkerTask *task = (WorkerTask *)arg;
    double sum = 0.0;
    for (uint32_t i = 0; i < task->count; i++) {
        uint32_t vec_idx = task->start_idx + i;
        float dot = sovra_18432d_dot(task->query, task->matrix + (vec_idx * DIM));
        sum += dot;
    }
    task->local_sum = sum;
    return NULL;
}

static int compare_doubles(const void *a, const void *b) {
    double da = *(const double *)a;
    double db = *(const double *)b;
    return (da > db) - (da < db);
}

int main(void) {
    float *query = (float *)aligned_alloc(64, DIM * sizeof(float));
    float *matrix = (float *)aligned_alloc(64, (size_t)TOTAL_VECTORS * DIM * sizeof(float));

    for (int i = 0; i < DIM; i++) query[i] = (i % 100) * 0.001f;
    for (size_t i = 0; i < (size_t)TOTAL_VECTORS * DIM; i++) matrix[i] = ((i + 1) % 100) * 0.001f;

    uint32_t vecs_per_core = TOTAL_VECTORS / NUM_CORES;
    pthread_t threads[NUM_CORES];
    WorkerTask tasks[NUM_CORES];

    // Warmup Pass (10 passes)
    for (int warm = 0; warm < 10; warm++) {
        for (int t = 0; t < NUM_CORES; t++) {
            tasks[t].query = query;
            tasks[t].matrix = matrix;
            tasks[t].start_idx = t * vecs_per_core;
            tasks[t].count = (t == NUM_CORES - 1) ? (TOTAL_VECTORS - tasks[t].start_idx) : vecs_per_core;
            pthread_create(&threads[t], NULL, sovra_worker, &tasks[t]);
        }
        for (int t = 0; t < NUM_CORES; t++) {
            pthread_join(threads[t], NULL);
            g_volatile_sink += tasks[t].local_sum;
        }
    }

    // Timed Iterations
    double sample_latencies_ms[ITERATIONS];
    double total_sum = 0.0;

    double t0_all = get_time_sec();
    for (int iter = 0; iter < ITERATIONS; iter++) {
        double iter_start = get_time_sec();

        for (int t = 0; t < NUM_CORES; t++) {
            tasks[t].query = query;
            tasks[t].matrix = matrix;
            tasks[t].start_idx = t * vecs_per_core;
            tasks[t].count = (t == NUM_CORES - 1) ? (TOTAL_VECTORS - tasks[t].start_idx) : vecs_per_core;
            pthread_create(&threads[t], NULL, sovra_worker, &tasks[t]);
        }

        for (int t = 0; t < NUM_CORES; t++) {
            pthread_join(threads[t], NULL);
            total_sum += tasks[t].local_sum;
        }

        double iter_end = get_time_sec();
        sample_latencies_ms[iter] = (iter_end - iter_start) * 1000.0;
    }
    double total_elapsed_sec = get_time_sec() - t0_all;
    g_volatile_sink += total_sum;

    double avg_pass_sec = total_elapsed_sec / ITERATIONS;
    double avg_pass_ms = avg_pass_sec * 1000.0;

    double ops_sec = TOTAL_VECTORS / avg_pass_sec;
    double gflops = ((double)TOTAL_VECTORS * DIM * 2.0) / (avg_pass_sec * 1e9);
    double gb_sec = (((double)TOTAL_VECTORS * DIM * 4.0) / (1024.0 * 1024.0 * 1024.0)) / avg_pass_sec;

    qsort(sample_latencies_ms, ITERATIONS, sizeof(double), compare_doubles);
    double p50_pass_ms = sample_latencies_ms[(int)(ITERATIONS * 0.50)];
    double p90_pass_ms = sample_latencies_ms[(int)(ITERATIONS * 0.90)];
    double p99_pass_ms = sample_latencies_ms[(int)(ITERATIONS * 0.99)];

    double p50_vec_us = (p50_pass_ms * 1000.0) / TOTAL_VECTORS;
    double p90_vec_us = (p90_pass_ms * 1000.0) / TOTAL_VECTORS;
    double p99_vec_us = (p99_pass_ms * 1000.0) / TOTAL_VECTORS;

    printf("{\n");
    printf("  \"language\": \"SOVRA C/NEON (clang -O3)\",\n");
    printf("  \"avg_pass_ms\": %.2f,\n", avg_pass_ms);
    printf("  \"evals_per_sec\": %.0f,\n", ops_sec);
    printf("  \"gflops\": %.2f,\n", gflops);
    printf("  \"bandwidth_gb_sec\": %.2f,\n", gb_sec);
    printf("  \"p50_us\": %.2f,\n", p50_vec_us);
    printf("  \"p90_us\": %.2f,\n", p90_vec_us);
    printf("  \"p99_us\": %.2f,\n", p99_vec_us);
    printf("  \"sink_check\": %.2f\n", g_volatile_sink);
    printf("}\n");

    free(query);
    free(matrix);
    return 0;
}

