//! Sovereign 18,432-Dimensional Hexological Vectoring Engine (Rust 1.95+)
//! Substrate: Apple Silicon M4 Bare Metal (10 CPU Cores, Rayon Multithreading)

use rayon::prelude::*;
use serde::Serialize;
use std::env;
use std::hint::black_box;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Instant;

const DIM: usize = 18432;
const TOTAL_VECTORS: usize = 100_000;
const ITERATIONS: usize = 20;

static GLOBAL_SINK: AtomicU64 = AtomicU64::new(0);

#[derive(Serialize)]
struct AuditReport {
    language: String,
    avg_pass_ms: f64,
    evals_per_sec: f64,
    gflops: f64,
    bandwidth_gb_sec: f64,
    p50_us: f64,
    p90_us: f64,
    p99_us: f64,
    sink_check: u64,
}

#[inline(always)]
fn hexological_18432d_dot_product(a: &[f32], b: &[f32]) -> f32 {
    debug_assert_eq!(a.len(), DIM);
    debug_assert_eq!(b.len(), DIM);

    let mut sum0 = 0.0f32;
    let mut sum1 = 0.0f32;
    let mut sum2 = 0.0f32;
    let mut sum3 = 0.0f32;

    let chunks_a = a.chunks_exact(4);
    let chunks_b = b.chunks_exact(4);

    for (ca, cb) in chunks_a.zip(chunks_b) {
        sum0 += ca[0] * cb[0];
        sum1 += ca[1] * cb[1];
        sum2 += ca[2] * cb[2];
        sum3 += ca[3] * cb[3];
    }

    sum0 + sum1 + sum2 + sum3
}

fn main() {
    let json_mode = env::args().any(|arg| arg == "--json");

    let query_vec: Vec<f32> = (0..DIM).map(|i| (i % 100) as f32 * 0.001).collect();
    let target_matrix: Vec<f32> = (0..(TOTAL_VECTORS * DIM))
        .map(|i| ((i + 1) % 100) as f32 * 0.001)
        .collect();

    // 1. Warmup Pass (10 passes)
    for _ in 0..10 {
        let warm_sum: f32 = target_matrix
            .par_chunks_exact(DIM)
            .map(|target_node| {
                black_box(hexological_18432d_dot_product(&query_vec, target_node))
            })
            .sum();
        GLOBAL_SINK.fetch_add(warm_sum.to_bits() as u64, Ordering::Relaxed);
    }

    // 2. Timed Iterations
    let mut sample_latencies_ms = Vec::with_capacity(ITERATIONS);
    let t_start_all = Instant::now();

    for _ in 0..ITERATIONS {
        let iter_start = Instant::now();
        let pass_sum: f32 = target_matrix
            .par_chunks_exact(DIM)
            .map(|target_node| {
                black_box(hexological_18432d_dot_product(&query_vec, target_node))
            })
            .sum();
        let iter_ms = iter_start.elapsed().as_secs_f64() * 1000.0;
        sample_latencies_ms.push(iter_ms);
        GLOBAL_SINK.fetch_add(pass_sum.to_bits() as u64, Ordering::Relaxed);
    }

    let total_elapsed_sec = t_start_all.elapsed().as_secs_f64();
    let avg_pass_sec = total_elapsed_sec / ITERATIONS as f64;
    let avg_pass_ms = avg_pass_sec * 1000.0;

    let evals_per_sec = TOTAL_VECTORS as f64 / avg_pass_sec;
    let gflops = (TOTAL_VECTORS as f64 * DIM as f64 * 2.0) / (avg_pass_sec * 1e9);
    let bytes_gb = (TOTAL_VECTORS as f64 * DIM as f64 * 4.0) / (1024.0 * 1024.0 * 1024.0);
    let bandwidth_gb_sec = bytes_gb / avg_pass_sec;

    sample_latencies_ms.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let p50_pass_ms = sample_latencies_ms[(ITERATIONS as f64 * 0.50) as usize];
    let p90_pass_ms = sample_latencies_ms[(ITERATIONS as f64 * 0.90) as usize];
    let p99_pass_ms = sample_latencies_ms[(ITERATIONS as f64 * 0.99) as usize];

    let p50_vec_us = (p50_pass_ms * 1000.0) / TOTAL_VECTORS as f64;
    let p90_vec_us = (p90_pass_ms * 1000.0) / TOTAL_VECTORS as f64;
    let p99_vec_us = (p99_pass_ms * 1000.0) / TOTAL_VECTORS as f64;

    let report = AuditReport {
        language: "Rust 1.95 (Cargo + Rayon)".to_string(),
        avg_pass_ms,
        evals_per_sec,
        gflops,
        bandwidth_gb_sec,
        p50_us: p50_vec_us,
        p90_us: p90_vec_us,
        p99_us: p99_vec_us,
        sink_check: GLOBAL_SINK.load(Ordering::Relaxed),
    };

    let report_json = serde_json::to_string_pretty(&report).unwrap();

    if json_mode {
        println!("{}", report_json);
    } else {
        println!("======================================================================");
        println!("  XORAS SOVEREIGN RUST 18,432-DIMENSIONAL HEXOLOGICAL VECTOR ENGINE");
        println!("======================================================================");
        println!("{}", report_json);
    }
}

// Calibrated Zig 0.16 18,432-D Hexological Vector Engine Benchmark
// Substrate: Apple Silicon M4 Bare Metal (ARM64 SIMD)

const std = @import("std");

const c = @cImport({
    @cInclude("time.h");
});

const DIM: usize = 18432;
const LANES: usize = 4;
const NUM_CORES: usize = 10;
const TOTAL_VECTORS: usize = 100000;
const ITERATIONS: usize = 20;

var g_volatile_sink: f64 = 0.0;

fn get_time_sec() f64 {
    var ts: c.struct_timespec = undefined;
    _ = c.clock_gettime(c.CLOCK_MONOTONIC, &ts);
    return @as(f64, @floatFromInt(ts.tv_sec)) + @as(f64, @floatFromInt(ts.tv_nsec)) / 1e9;
}

inline fn zig_18432d_dot_product(a: []const f32, b: []const f32) f32 {
    var acc0: @Vector(LANES, f32) = @splat(0.0);
    var acc1: @Vector(LANES, f32) = @splat(0.0);

    var i: usize = 0;
    while (i < DIM) : (i += LANES * 2) {
        const va0: @Vector(LANES, f32) = a[i..][0..LANES].*;
        const vb0: @Vector(LANES, f32) = b[i..][0..LANES].*;
        acc0 += va0 * vb0;

        const va1: @Vector(LANES, f32) = a[i + LANES ..][0..LANES].*;
        const vb1: @Vector(LANES, f32) = b[i + LANES ..][0..LANES].*;
        acc1 += va1 * vb1;
    }

    const sum_vec = acc0 + acc1;
    return @reduce(.Add, sum_vec);
}

const WorkerContext = struct {
    query: []const f32,
    targets: []const f32,
    count: usize,
    sum: *f64,
};

fn worker_fn(ctx: WorkerContext) void {
    const query = ctx.query;
    const targets = ctx.targets;
    const count = ctx.count;

    var local_sum: f64 = 0.0;
    var i: usize = 0;
    while (i < count) : (i += 1) {
        const offset = i * DIM;
        const target = targets[offset .. offset + DIM];
        const dot = zig_18432d_dot_product(query, target);
        local_sum += dot;
    }
    ctx.sum.* = local_sum;
}

pub fn main() !void {
    const allocator = std.heap.page_allocator;

    const query_vec = try allocator.alloc(f32, DIM);
    defer allocator.free(query_vec);

    const target_matrix = try allocator.alloc(f32, TOTAL_VECTORS * DIM);
    defer allocator.free(target_matrix);

    for (query_vec, 0..) |*val, idx| {
        val.* = @as(f32, @floatFromInt(idx % 100)) * 0.001;
    }
    for (target_matrix, 0..) |*val, idx| {
        val.* = @as(f32, @floatFromInt((idx + 1) % 100)) * 0.001;
    }

    const vecs_per_core = TOTAL_VECTORS / NUM_CORES;
    var threads: [NUM_CORES]std.Thread = undefined;
    var thread_sums: [NUM_CORES]f64 = undefined;

    // 1. Warmup Pass (10 passes)
    var warm: usize = 0;
    while (warm < 10) : (warm += 1) {
        var t: usize = 0;
        while (t < NUM_CORES) : (t += 1) {
            const count = if (t == NUM_CORES - 1) (TOTAL_VECTORS - t * vecs_per_core) else vecs_per_core;
            const start_idx = t * vecs_per_core;

            const ctx = WorkerContext{
                .query = query_vec,
                .targets = target_matrix[start_idx * DIM .. (start_idx + count) * DIM],
                .count = count,
                .sum = &thread_sums[t],
            };

            threads[t] = try std.Thread.spawn(.{}, worker_fn, .{ctx});
        }
        for (&threads) |*thread| {
            thread.join();
        }
    }

    // 2. Timed Iterations
    var sample_latencies_ms: [ITERATIONS]f64 = undefined;
    const t_start_all = get_time_sec();

    var iter: usize = 0;
    while (iter < ITERATIONS) : (iter += 1) {
        const iter_start = get_time_sec();

        var t: usize = 0;
        while (t < NUM_CORES) : (t += 1) {
            const count = if (t == NUM_CORES - 1) (TOTAL_VECTORS - t * vecs_per_core) else vecs_per_core;
            const start_idx = t * vecs_per_core;

            const ctx = WorkerContext{
                .query = query_vec,
                .targets = target_matrix[start_idx * DIM .. (start_idx + count) * DIM],
                .count = count,
                .sum = &thread_sums[t],
            };

            threads[t] = try std.Thread.spawn(.{}, worker_fn, .{ctx});
        }

        for (&threads) |*thread| {
            thread.join();
        }

        for (thread_sums) |s| {
            g_volatile_sink += s;
        }

        const iter_end = get_time_sec();
        sample_latencies_ms[iter] = (iter_end - iter_start) * 1000.0;
    }

    const total_elapsed_sec = get_time_sec() - t_start_all;
    const avg_pass_sec = total_elapsed_sec / @as(f64, @floatFromInt(ITERATIONS));
    const avg_pass_ms = avg_pass_sec * 1000.0;

    const ops_sec = @as(f64, @floatFromInt(TOTAL_VECTORS)) / avg_pass_sec;
    const gflops = (@as(f64, @floatFromInt(TOTAL_VECTORS)) * @as(f64, @floatFromInt(DIM)) * 2.0) / (avg_pass_sec * 1e9);
