    for (size_t i = 0; i < task->node_count; i++) {
        size_t node_idx = task->start_node + i;
        const float *target = task->matrix_mmap + (node_idx * DIM);
        float dot = sovra_18432d_dot_neon(task->query, target);
        sum += dot;
    }
    task->local_sum = sum;
    return NULL;
}

