#!/usr/bin/env python3
import hashlib, json, os, sys, subprocess

def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()

def verify_artifact(kind, ref):
    if kind == "file_exists":
        return os.path.isfile(ref), f"file:{ref}"
    if kind == "file_hash":
        if ":" not in ref:
            return False, f"invalid_ref:{ref}"
        path, expect = ref.split(":", 1)
        if not os.path.exists(path):
            return False, f"file_not_found:{path}"
        got = sha256_file(path)
        return got == expect, f"hash:{path}={got}"
    if kind == "cmd_exit":
        rc = subprocess.run(ref, shell=True).returncode
        return rc == 0, f"cmd:{ref} -> {rc}"
    if kind == "test_pass":
        rc = subprocess.run(f"python3 -m pytest {ref} -q", shell=True).returncode
        return rc == 0, f"test:{ref} -> {rc}"
    return False, f"unknown_kind:{kind}"

def commit_node(agent, kind, ref, payload):
    ok, receipt = verify_artifact(kind, ref)
    if not ok:
        print(f"REJECTED: {agent} tried to commit '{payload}' — no evidence: {receipt}")
        sys.exit(1)
    node = {
        "agent": agent,
        "payload": payload,
        "evidence_kind": kind,
        "evidence_ref": ref,
        "receipt": receipt,
        "ts": subprocess.run(["date", "-u", "+%Y-%m-%dT%H:%M:%SZ"], capture_output=True, text=True).stdout.strip(),
    }
    print(json.dumps(node, indent=2))
    dag_path = "/Users/ajoxendine68/Desktop/SSOT_Agentic_Brain/memory/catch_log/dag.jsonl"
    os.makedirs(os.path.dirname(dag_path), exist_ok=True)
    with open(dag_path, "a") as f:
        f.write(json.dumps(node) + "\n")

    nodes = [json.loads(line) for line in open(dag_path) if line.strip()]
    root = hashlib.sha256("".join(json.dumps(n, sort_keys=True) for n in nodes).encode()).hexdigest()
    print(f"ROOT: {root}")

